/* Source: https://onechauffeur.fr/wp-content/plugins/chauffeur-booking-system/style/public.demo.css */
ul.chbs-demo-menu
{
	padding:0px;
	font-size:0px;
	list-style-type:none;
	margin:0px 0px 20px 0px;
}

	ul.chbs-demo-menu li
	{
		padding:0px;
		display:inline-block;
		margin:0px 31px 10px 0px;
	}

	ul.chbs-demo-menu li:last-child
	{
		margin-right:0px;
	}

		ul.chbs-demo-menu li a
		{
			color:#6F7687;
			display:block;
			font-size:15px;
			font-weight:700;
			line-height:24px;
			border-radius:5px;
			font-family:'Lato';
			white-space:nowrap;
			text-decoration:none;
			padding:0px 0px 2px 0px;
			transition:color 0.2s ease 0s;
		}

		ul.chbs-demo-menu li:first-child a
		{
			color:#232732;
			pointer-events:none;
		}

		ul.chbs-demo-menu li:first-child a::after
		{
			display:none;
		}

		ul.chbs-demo-menu li a::after
		{
			width:100%;
			height:2px;
			content:"";
			display:block;
			position:relative;
			background:#232732;
			transform:scaleX(0);
			transform-origin:left;
			transition:transform 0.2s ease 0s;
		}

		ul.chbs-demo-menu li:not(:first-child):hover a
		{
			color:#232732;
		}

		ul.chbs-demo-menu li:hover a::after
		{
			transform:scaleX(1);
		}

		ul.chbs-demo-menu li.current_page_item a,
		ul.chbs-demo-menu li.current-chbs-demo-menu-item a
		{
			transform:scaleX(1);
			color:#232732;
		}

		ul.chbs-demo-menu li.current_page_item a::after,
		ul.chbs-demo-menu li.current-chbs-demo-menu-item a::after
		{
			transform:scaleX(1);
		}

div.chbs-demo-description
{
	display:flex;
	row-gap:30px;
	padding:30px;
	color:#4B515A;
	flex-wrap:wrap;
	font-size:14px;
	font-weight:400;
	column-gap:20px;
	line-height:26px;
	border-radius:5px;
	font-family:'Lato';
	flex-direction:row;
	margin-bottom:50px;
	background-color:#F5F6F7;
}

